  const V = window.__vt && window.__vt.views;
  const c = $('taste-crt');
  if (!V || !V.map || !V.map.points || !c) return [];
  const r = c.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const w = c.width, h = c.height, k = r.width / w;
  const pts = V.map.points;
  const xs = pts.map((p) => p.x), ys = pts.map((p) => p.y);
  const pad = 34 * dpr;
  const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
  const sx = (v) => pad + ((v - x0) / Math.max(1e-9, x1 - x0)) * (w - 2 * pad);
  const sy = (v) => pad + ((v - y0) / Math.max(1e-9, y1 - y0)) * (h - 2 * pad);
  const fitted = !!V.styles;
  const names = new Map((V.ranked || []).map((q) => [q.id, q.name]));
  return pts.filter((p) => p.id != null).map((p) => {
    const base = p.origin === 'edited' ? 5.5 : p.origin === 'refined' ? 4.8 : 4;
    const unsure = p.utility_std != null ? Math.min(1, p.utility_std) : 0;
    return { id: p.id, name: names.get(p.id) || ('#' + p.id), x: Math.round(r.left + sx(p.x) * k), y: Math.round(r.top + sy(p.y) * k),
      glow: fitted ? 1 / (1 + Math.exp(-p.utility)) : null, std: p.utility_std, rad: +((base + unsure * 3.5)).toFixed(1), style: p.style };
  });
};
