const marker = (id, d) => {
  let m = document.getElementById(id);
  if (!m) { m = document.createElement('div'); m.id = id; document.body.appendChild(m); }
  Object.assign(m.style, { position: 'fixed', left: (d.x - 1) + 'px', top: (d.y - 1) + 'px', width: '2px', height: '2px', pointerEvents: 'none', opacity: '0', zIndex: '0' });
  m.dataset.name = d.name; m.dataset.id = d.id;
  return d.name + ' #' + d.id + ' at ' + d.x + ',' + d.y + ' glow ' + (d.glow == null ? '-' : d.glow.toFixed(2)) + ' std ' + (d.std == null ? '-' : d.std.toFixed(2));
