  return names.map((name, i) => {
    const y = rowH * (i + 1);
    const bars = styles.map((s, si) => {
      const t = s.theta.find((q) => q.name === name); if (!t) return null;
      const yy = y + (si - (styles.length - 1) / 2) * lane, len = (t.mean / maxAbs) * barMax, wl = Math.min((t.std / maxAbs) * barMax, usable * 0.3);
      return { k: s.k, mean: +t.mean.toFixed(3), std: +t.std.toFixed(3), x: Math.round(r.left + (cx + len) * k), y: Math.round(r.top + yy * k),
        lo: Math.round(r.left + (cx + len - wl) * k), hi: Math.round(r.left + (cx + len + wl) * k), crosses: cx + len - wl < cx && cx + len + wl > cx };
    }).filter(Boolean);
